BEGIN;
SET LOCAL lock_timeout='3s'; SET LOCAL statement_timeout='30s';
DO $q$
DECLARE t population_top3000_202608_202609_v1.pipeline_task%rowtype; c jsonb; ev bigint; d text; wait_seconds double precision;
BEGIN
 PERFORM population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=28281 AND event='ENGINEERING_ASSIGNMENT_CLAIMED_V5' AND (details->>'expires_at')::timestamptz>clock_timestamp()) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event IN('ENGINEERING_ASSIGNMENT_COMPLETED_V5','ENGINEERING_ASSIGNMENT_EFFECTS_RECONCILED_RELEASE_V5') AND details->>'claim_event_id'='28281') THEN RAISE EXCEPTION 'CURRENT_CLAIM_REQUIRED';END IF;
 SELECT * INTO STRICT t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id='SOURCE_TASK_ID'::uuid FOR UPDATE;
 IF t.family_id<>'REF01' OR t.stage<>'ACQUIRE' OR t.input_versions->>'assignment_event_id'<>'28270' OR t.payload->>'kind'<>'REF01_CENSUS_SOURCE_V1' OR t.status<>'BLOCKED' OR t.blocker_code<>'DEPENDENCY_PENDING' OR t.resumption_condition->>'event'<>'PROVIDER_SLOT_AVAILABLE' OR t.recheck_count<>12 OR t.max_rechecks<>12 OR t.cumulative_failures<>0 OR t.executions>=t.max_executions THEN RAISE EXCEPTION 'EXACT_FINITE_PROVIDER_WAIT_REQUIRED';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.connector_probe_lease_v1 WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_job WHERE status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_attempt WHERE outcome='RUNNING') THEN RAISE EXCEPTION 'PROVIDER_SLOT_NOT_CLEAR';END IF;
 SELECT greatest(0,extract(epoch FROM next_provider_at-clock_timestamp())) INTO wait_seconds FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton;
 IF wait_seconds>2 THEN RAISE EXCEPTION 'PROVIDER_WAIT_EXCEEDS_TWO_SECONDS';END IF;
 IF wait_seconds>0 THEN PERFORM pg_sleep(wait_seconds);END IF;
 IF (SELECT next_provider_at>clock_timestamp() FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton) THEN RAISE EXCEPTION 'PROVIDER_TIME_NOT_CLEAR';END IF;
 c:=population_top3000_202608_202609_v1.ref01_date_context_v4(t.task_id);d:=c->>'as_of';
 IF d NOT IN('2026-08-04','2026-08-05') OR c->>'state'<>'READY' OR (c->>'page_number')::int NOT BETWEEN 2 AND 14 OR (SELECT count(*) FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='REF01_DATE_PROVIDER_WAIT_OPERATIONAL_REQUEUE_V5' AND details->>'task_id'=t.task_id::text)>=2 THEN RAISE EXCEPTION 'EXACT_RETAINED_SOURCE_ADMISSION_OR_REQUEUE_BOUND';END IF;
 UPDATE population_top3000_202608_202609_v1.pipeline_task SET status='READY',blocker_code=NULL,blocker_until=NULL,resumption_condition=NULL WHERE task_id=t.task_id;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details)VALUES('REF01_DATE_PROVIDER_WAIT_OPERATIONAL_REQUEUE_V5',jsonb_build_object('assignment_event_id',28270,'claim_event_id',28281,'executor','automation:6adc2c96db348191bca7cf4eacfdac32','task_id',t.task_id,'as_of',d,'prior_checkpoint',t.checkpoint,'recheck_count_preserved',t.recheck_count,'executions_preserved',t.executions,'failure_count_preserved',t.cumulative_failures,'source_limits_unchanged',true,'all_counters_preserved',true,'independent_review',REVIEW_JSON::jsonb));
 PERFORM population_top3000_202608_202609_v1.pipeline_tick_v1();
END;$q$;
SELECT event_id,details FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='REF01_DATE_PROVIDER_WAIT_OPERATIONAL_REQUEUE_V5' ORDER BY event_id DESC LIMIT 1;
COMMIT;
